# In a multi-table statement only a chain made entirely of INNER JOINs is
# eligible: every source row that can reach the WHERE result must reach it
# through matches on both sides, so a condition referencing one source
# alone may prune that source's groups exactly as in the single-file case.
# Any OUTER step can emit padded rows, so no group pruning is applied to
# such chains.  Leaves are grouped per source from the *unbound* WHERE tree
# (so the grouping never depends on having a file's schema), and each
# source's own bound tree -- which shares the WHERE's parse identity node
# for node -- provides the bound leaves in the same order.

_FLIP_CMP_OP = {"=": "=", "!=": "!=", "<": ">", "<=": ">=", ">": "<", ">=": "<="}


def _is_pushable_leaf(node: tuple) -> bool:
    """Whether a bound WHERE leaf can be checked against column statistics."""
    tag = node[0]
    if tag == "isnull":
        return node[1][0] == "column"
    if tag == "cmp":
        left, right = node[2], node[3]
        return (left[0] == "column" and right[0] == "literal") or (
            left[0] == "literal" and right[0] == "column"
        )
    return False


def _is_pushable_leaf_parsed(node: tuple) -> bool:
    """Same shape check as :func:`_is_pushable_leaf` for an unbound tree."""
    tag = node[0]
    if tag == "isnull":
        return node[1][0] == "column"
    if tag == "cmp":
        left, right = node[2], node[3]
        return (left[0] == "column" and right[0] == "literal") or (
            left[0] == "literal" and right[0] == "column"
        )
    return False


def _walk_top_and_leaves(node: tuple, pushable, sink) -> None:
    """Feed the top-level AND-connected pushable leaves to ``sink``.

    Only the AND spine at the root is unfolded; leaves nested under OR,
    NOT or any other non-AND node are never visited.  Non-pushable leaves
    sitting directly on the AND spine are simply skipped, so they neither
    prune groups nor block the pushdown of their eligible siblings.
    """
    if node[0] == "and":
        _walk_top_and_leaves(node[1], pushable, sink)
        _walk_top_and_leaves(node[2], pushable, sink)
    elif pushable(node):
        sink(node)


def _extract_pushable(where: tuple | None) -> list:
    """The AND-connected pushable leaves of a bound WHERE tree, in order."""
    conditions: list = []
    if where is not None:
        _walk_top_and_leaves(where, _is_pushable_leaf, conditions.append)
    return conditions


def _column_leaf_source(node: tuple) -> str | None:
    """The qualified source name of a parsed pushable leaf's sole column.

    Returns ``None`` for an unqualified column (single-table statements)
    or for anything whose column shape is not exactly one qualified
    column versus a literal.
    """
    if node[0] == "isnull":
        column = node[1]
    else:
        left, right = node[2], node[3]
        column = left if left[0] == "column" else right
    table = column[2]
    if table is None:
        return None
    return f"{table}.{column[1]}"


def _extract_pushable_by_source(where: tuple | None, table_keys: tuple) -> dict:
    """Top-level AND pushable leaves of an unbound WHERE tree, keyed by source.

    Only qualified leaves referencing exactly one listed source are
    collected; each source maps to its leaves in SQL appearance order.
    """
    by_source: dict = {key: [] for key in table_keys}

    def sink(node: tuple) -> None:
        name = _column_leaf_source(node)
        if name is not None:
            for key in table_keys:
                if name.startswith(f"{key}."):
                    by_source[key].append(node)
                    return

    if where is not None:
        _walk_top_and_leaves(where, _is_pushable_leaf_parsed, sink)
    return by_source


