    """The qualified name of a bound pushable leaf's column."""
    column = node[1] if node[0] == "isnull" else (
        node[2] if node[2][0] == "column" else node[3]
    )
    return schema.columns[column[2]].name


def _bound_pushable_by_source(bound_where: tuple, schema: Schema, table_keys: tuple) -> dict:
    """Top-level AND pushable leaves of the bound WHERE tree, keyed by source.

    The bound tree mirrors the parsed tree node for node (rewriting only
    changes column nodes), so appearance order and source grouping match
    :func:`_extract_pushable_by_source`.
    """
    by_source: dict = {key: [] for key in table_keys}

    def sink(node: tuple) -> None:
        name = _bound_leaf_source(node, schema)
        for key in table_keys:
            if name.startswith(f"{key}."):
                by_source[key].append(node)
                return

    _walk_top_and_leaves(bound_where, _is_pushable_leaf, sink)
    return by_source

