import json, struct, os
from columnar_analytics import *

LA=Schema([ColumnSchema("id","int64"),ColumnSchema("n","int64",nullable=True)])
DA={"id":[1,2,3,4,5,6,7,8],"n":[10,None,30,40,None,60,70,80]}
LB=Schema([ColumnSchema("k","int64"),ColumnSchema("t","utf8",nullable=True)])
DB={"k":[1,2,3,4,5,6,7,8],"t":["a","b",None,"c","a","b",None,"c"]}
d="/tmp/jt5"; os.makedirs(d,exist_ok=True)
ap=f"{d}/a.caef"; bp=f"{d}/b.caef"
G=4
def rewrite(): write_partitioned_file(ap,Table(LA,DA),2); write_partitioned_file(bp,Table(LB,DB),2)
def corrupt(path,g,colname):
    blob=bytearray(open(path,'rb').read())
    hl=struct.unpack("<I",blob[5:9])[0]
    h=json.loads(bytes(blob[9:9+hl]).decode())
    ci=[c["name"] for c in h["columns"]].index(colname)
    b=h["row_groups"][g]["columns"][ci]
    blob[9+hl+b["offset"]]^=0xFF
    open(path,'wb').write(bytes(blob))
rewrite()

wheres = ["WHERE a.n > 50","WHERE a.n IS NULL","WHERE b.t = 'a'",
          "WHERE a.n < 25 AND b.t IS NOT NULL","WHERE a.n > 1000","WHERE b.t IS NULL",
          "WHERE a.n = 40 OR b.t = 'z'","WHERE a.n >= 30 AND a.n <= 70"]
ok=True
for w in wheres:
    for join in ["INNER JOIN","LEFT JOIN"]:
        sqlj=f"SELECT a.id, b.t FROM a {join} b ON a.id = b.k {w}"
        plan=explain_files({"a":ap,"b":bp},sqlj)
        scans={op["source"]:op for op in plan["operators"] if op["operator"]=="Scan"}
        for src,path,keycol in (("a",ap,"id"),("b",bp,"k")):
            observed=set()
            for g in range(G):
                rewrite(); corrupt(path,g,keycol)
                try:
                    query_files({"a":ap,"b":bp},sqlj); raised=False
                except ColumnarFormatError: raised=True
                if raised: observed.add(g)
            rewrite()
            sel_field=scans[src]["row_groups_selected"]
            if len(observed)!=sel_field:
                ok=False; print("MISMATCH", join, w, src, observed, sel_field)
print("explain/read group-set consistent:", ok)

LC=Schema([ColumnSchema("cid","int64"),ColumnSchema("jc","int64"),ColumnSchema("u","utf8",nullable=True)])
DC={"cid":[1,2,3,4,5,6],"jc":[1,2,3,4,5,6],"u":["p","q",None,"p","q",None]}
cp=f"{d}/c.caef"; write_partitioned_file(cp,Table(LC,DC),2)
write_file(ap,Table(LA,DA))
sql="SELECT a.id, b.t, c.u FROM a INNER JOIN b ON a.id=b.k INNER JOIN c ON b.k=c.jc WHERE c.u = 'p'"
plan=explain_files({"a":ap,"b":bp,"c":cp},sql)
for op in plan["operators"]:
    if op["operator"]=="Scan":
        print(op["source"], "total", op.get("row_groups_total"), "sel", op.get("row_groups_selected"),
              "pushed", (op.get("pushed_condition") or {}).get("kind") if op.get("pushed_condition") else None)
obs=set()
for g in range(3):
    corrupt(cp,g,"jc")
    try: query_files({"a":ap,"b":bp,"c":cp},sql)
    except ColumnarFormatError: obs.add(g)
    write_partitioned_file(cp,Table(LC,DC),2)
print("c read groups (expect only selected):", obs)
